<script setup lang="ts">
import { moderatorApi } from '~/services/moderator.api'
import type { Product } from '~/types/catalog'
definePageMeta({ layout: 'moderator', middleware: 'moderator' })
const { data: products, pending, error, refresh } = await useAsyncData<Product[]>('moderator-products', async () => (await moderatorApi.products()).productsAdmin)
const busy = ref<string>()
async function toggle(id: string, published: boolean) { busy.value = id; try { await moderatorApi.publish(id, !published); await refresh() } finally { busy.value = undefined } }
</script>
<template><div><div class="flex flex-wrap items-end justify-between gap-4"><div><p class="text-xs font-bold uppercase tracking-widest text-slate-500">Catalogue control</p><h1 class="mt-2 font-display text-4xl">Products</h1></div><NuxtLink to="/moderator/products/new" class="button-primary">Create product</NuxtLink></div><p v-if="error" class="mt-7 rounded-lg bg-rose-50 p-4 text-rose-800">Unable to load products.</p><div v-else class="card mt-8 overflow-x-auto"><table class="w-full min-w-[720px] text-left text-sm"><thead class="border-b bg-slate-50 text-slate-600"><tr><th class="p-4">Product</th><th class="p-4">Status</th><th class="p-4">Price</th><th class="p-4">Inventory</th><th class="p-4"></th></tr></thead><tbody><tr v-if="pending"><td colspan="5" class="p-6 text-slate-500">Loading products…</td></tr><tr v-for="product in products" :key="product.id" class="border-b last:border-0"><td class="p-4 font-semibold">{{ product.name }}<span class="ml-2 font-normal text-slate-500">{{ product.category.name }}</span></td><td class="p-4"><span class="rounded-full px-2 py-1 text-xs font-bold" :class="product.published ? 'bg-emerald-100 text-emerald-800' : 'bg-slate-100 text-slate-600'">{{ product.published ? 'Published' : 'Hidden' }}</span></td><td class="p-4">{{ useMoney(product.price) }}</td><td class="p-4">{{ product.variants.reduce((total, item) => total + item.stock, 0) }}</td><td class="p-4"><NuxtLink :to="`/moderator/products/${product.id}`" class="mr-4 font-bold underline">Edit</NuxtLink><button class="font-bold underline" :disabled="busy === product.id" @click="toggle(product.id, product.published)">{{ product.published ? 'Hide' : 'Publish' }}</button></td></tr></tbody></table></div></div></template>
